<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                 const actualValue = current[0];
                 if (typeof actualValue === 'boolean') {
                     return actualValue;
                 }
                 return String(actualValue);
            } else {
                return defaultValue;
            }
        }
        if (typeof current === 'boolean') {
            return current;
        }
        return String(current);
    }

    function updateProgressBar(barId, valueMainId, valueDescId, handleId, rawValueFromCharacterData, min, max) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);
        const sliderHandle = document.getElementById(handleId);

        if (!valueMainDisplay || !sliderHandle) {
            console.log(`Missing elements: ${valueMainId} or ${handleId}`);
            return;
        }

        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;
        let descriptionText = "";

        const descriptionMatch = String(fullDisplayString).match(/\((.+)\)$/);
        if (descriptionMatch && descriptionMatch[1]) {
            descriptionText = descriptionMatch[1];
            fullDisplayString = String(fullDisplayString).substring(0, descriptionMatch.index).trim();
        }

        const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=[^\d.]*$|->)/);
         if (valueMatch) {
            numericValue = parseFloat(valueMatch[1]);
            const parts = String(fullDisplayString).split('->');
            valueMainDisplay.innerText = parts.length > 1 ? parts[1].trim() : parts[0].trim();
         } else if (!isNaN(parseFloat(fullDisplayString))) {
             numericValue = parseFloat(fullDisplayString);
             valueMainDisplay.innerText = fullDisplayString;
         } else {
             if (Array.isArray(rawValueFromCharacterData) && typeof rawValueFromCharacterData[0] === 'number') {
                 numericValue = rawValueFromCharacterData[0];
                 valueMainDisplay.innerText = String(numericValue);
             } else if (typeof rawValueFromCharacterData === 'number') {
                 numericValue = rawValueFromCharacterData;
                 valueMainDisplay.innerText = String(rawValueFromCharacterData);
             } else if (typeof rawValueFromCharacterData === 'string') {
                 const parsed = parseFloat(rawValueFromCharacterData);
                 if (!isNaN(parsed)) {
                     numericValue = parsed;
                     valueMainDisplay.innerText = rawValueFromCharacterData;
                 } else {
                     valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
                 }
             } else {
                 valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
             }
         }

        if (valueDescDisplay) {
            valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";
        }

        // 确保数值在范围内
        numericValue = Math.max(min, Math.min(max, numericValue));

        // 计算百分比 (0-100)
        const range = max - min;
        const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;

        console.log(`${barId}: value=${numericValue}, percentage=${percentage}%`);

        // 设置进度条透明度
        if (progressBar) {
            const opacity = Math.max(0.1, percentage / 100);
            progressBar.style.opacity = opacity.toFixed(2);
        }

        // 设置滑块位置 - 关键修复！
        if (sliderHandle) {
            // 直接使用百分比设置位置，并考虑滑块宽度的一半作为偏移
            const offsetPercentage = percentage - (8 / sliderHandle.parentElement.offsetWidth) * 100;
            const finalPosition = Math.max(0, Math.min(100, offsetPercentage));
            sliderHandle.style.left = `${finalPosition}%`;
            console.log(`Slider ${handleId}: position set to ${finalPosition}%`);
        }
    }

    function toggleMainCard() {
        const card = document.getElementById('status-card');
        card.classList.toggle('collapsed');
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                 return;
            }

            console.log('Character data loaded:', characterData);

            const characterKey = "潘多拉";

            if (characterData.hasOwnProperty(characterKey)) {
                console.log('Found character data for:', characterKey);

                // 使用setTimeout确保DOM完全加载
                setTimeout(() => {
                    updateProgressBar(
                        'pandora-affection-bar',
                        'pandora-affection',
                        'pandora-affection-desc',
                        'pandora-affection-handle',
                        SafeGetValue(characterData, `${characterKey}.好感度`),
                        0,
                        100
                    );

                    updateProgressBar(
                        'pandora-ambiguity-bar',
                        'pandora-ambiguity',
                        'pandora-ambiguity-desc',
                        'pandora-ambiguity-handle',
                        SafeGetValue(characterData, `${characterKey}.暧昧值`),
                        0,
                        100
                    );

                    updateProgressBar(
                        'pandora-relationship-bar',
                        'pandora-relationship',
                        'pandora-relationship-desc',
                        'pandora-relationship-handle',
                        SafeGetValue(characterData, `${characterKey}.弟弟或是恋人`),
                        0,
                        100
                    );

                    updateProgressBar(
                        'pandora-mood-bar',
                        'pandora-mood',
                        'pandora-mood-desc',
                        'pandora-mood-handle',
                        SafeGetValue(characterData, `${characterKey}.心情值`),
                        0,
                        100
                    );

                    updateProgressBar(
                        'pandora-drunk-bar',
                        'pandora-drunk',
                        'pandora-drunk-desc',
                        'pandora-drunk-handle',
                        SafeGetValue(characterData, `${characterKey}.醉酒度`),
                        0,
                        100
                    );

                    updateProgressBar(
                        'pandora-desire-bar',
                        'pandora-desire',
                        'pandora-desire-desc',
                        'pandora-desire-handle',
                        SafeGetValue(characterData, `${characterKey}.欲望值`),
                        0,
                        100
                    );
                }, 200);
            } else {
                 console.log('Character data not found for:', characterKey);
                 // 重置所有显示元素
                 const elements = [
                     'pandora-affection', 'pandora-ambiguity', 'pandora-relationship',
                     'pandora-mood', 'pandora-drunk', 'pandora-desire'
                 ];

                 elements.forEach(id => {
                     const mainEl = document.getElementById(id);
                     const descEl = document.getElementById(id + '-desc');
                     const handleEl = document.getElementById(id + '-handle');

                     if (mainEl) mainEl.innerText = 'N/A';
                     if (descEl) descEl.innerText = '(数据缺失)';
                     if (handleEl) handleEl.style.left = '0%';
                 });
            }
        } catch (error) {
            console.error('Error in initDisplay:', error);
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
